import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  LinearProgress,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../../services/api';
import ApplicationWarningResolver from '../shared/ApplicationWarningResolver';
import { DataQualityReadinessCard } from './DataQualityReadinessCard';
import { READINESS_ACTION_LABELS } from '../../constants/orchestrationUxLabels';

interface ChecklistItem {
  id?: string;
  title?: string;
  description?: string;
  status?: string;
}

interface ChecklistSection {
  section?: string;
  readinessScore?: number;
  items?: ChecklistItem[];
}

interface IsoGapChecklist {
  overallReadinessScore?: number;
  sections?: Record<string, ChecklistSection>;
  openGaps?: Array<{ title?: string; description?: string; priority?: string }>;
  priorityActions?: Array<{
    title?: string;
    description?: string;
    action?: string;
    detail?: string;
    priority?: string;
    hubLink?: string;
    actionLabel?: string;
    gapId?: string;
  }>;
}

const sectionTitle = (key: string): string =>
  key
    .replace(/([A-Z])/g, ' $1')
    .replace(/^./, (s) => s.toUpperCase())
    .trim();

export const IsoGapClosurePanel: React.FC<{ period?: string }> = ({ period = 'annual' }) => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [checklist, setChecklist] = useState<IsoGapChecklist | null>(null);
  const [dataQualityReadiness, setDataQualityReadiness] = useState<{
    threshold?: number;
    confidence?: number;
    passed?: boolean;
    effect?: string;
    relationToEmissions?: string;
  } | null>(null);
  const [applying, setApplying] = useState(false);
  const [applyMessage, setApplyMessage] = useState<string | null>(null);

  const loadChecklist = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [res, isoRes] = await Promise.all([
        ApiService.getIsoGapClosureChecklist({ period, framework: 'all' }),
        ApiService.getISO14064Report({ period }).catch(() => null),
      ]);
      setChecklist((res?.data?.checklist as IsoGapChecklist) || null);
      const isoReport = (isoRes as { data?: { dataQualityReadiness?: typeof dataQualityReadiness } })?.data;
      setDataQualityReadiness(isoReport?.dataQualityReadiness || null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Unable to load ISO gap closure checklist');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    void loadChecklist();
  }, [loadChecklist]);

  const applyImprovements = async () => {
    setApplying(true);
    setApplyMessage(null);
    try {
      const result = await ApiService.runComplianceHubAutopilot({ period, applyChanges: true });
      const count = result?.data?.closuresApplied?.length ?? result?.closuresApplied?.length ?? 0;
      setApplyMessage(
        count > 0
          ? `Applied ${count} readiness improvement(s) from bills, ISO gaps, and PCF templates.`
          : 'Autopilot completed — review updated readiness scores.'
      );
      await loadChecklist();
    } catch (e) {
      setApplyMessage(e instanceof Error ? e.message : 'Could not apply readiness improvements.');
    } finally {
      setApplying(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  if (error) {
    return <Alert severity="error">{error}</Alert>;
  }

  if (!checklist) {
    return <Alert severity="info">No ISO gap-closure checklist available yet.</Alert>;
  }

  const sections = Object.entries(checklist.sections || {});

  return (
    <Stack spacing={2}>
      <Card variant="outlined">
        <CardContent>
          <Typography variant="subtitle2" color="text.secondary" gutterBottom>
            Overall ISO 14064 / 14067 readiness
          </Typography>
          <Stack direction="row" alignItems="center" spacing={2}>
            <Typography variant="h4">{checklist.overallReadinessScore ?? 0}%</Typography>
            <Box sx={{ flex: 1 }}>
              <LinearProgress
                variant="determinate"
                value={Math.min(100, checklist.overallReadinessScore ?? 0)}
                sx={{ height: 8, borderRadius: 1 }}
              />
            </Box>
            <Button
              variant="contained"
              size="small"
              disabled={applying}
              onClick={() => { void applyImprovements(); }}
            >
              {applying ? 'Applying…' : READINESS_ACTION_LABELS.autoFixFromDocuments}
            </Button>
          </Stack>
          {applyMessage && (
            <Alert severity="info" sx={{ mt: 2 }}>
              {applyMessage}
            </Alert>
          )}
        </CardContent>
      </Card>

      {dataQualityReadiness ? (
        <DataQualityReadinessCard
          readiness={dataQualityReadiness}
          title="Inventory data quality (ISO 14064)"
        />
      ) : null}

      {sections.map(([key, section]) => (
        <Card key={key} variant="outlined">
          <CardContent>
            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
              <Typography variant="subtitle1">{sectionTitle(key)}</Typography>
              <Chip size="small" label={`${section.readinessScore ?? 0}%`} color="primary" variant="outlined" />
            </Stack>
            <List dense disablePadding>
              {(section.items || []).map((item) => (
                <ListItem key={item.id || item.title} disableGutters>
                  <ListItemText
                    primary={
                      <Stack direction="row" spacing={1} alignItems="center">
                        <Chip
                          size="small"
                          label={item.status === 'complete' ? 'Complete' : 'Open'}
                          color={item.status === 'complete' ? 'success' : 'warning'}
                          variant="outlined"
                        />
                        <Typography variant="body2">{item.title}</Typography>
                      </Stack>
                    }
                    secondary={item.description}
                  />
                </ListItem>
              ))}
            </List>
          </CardContent>
        </Card>
      ))}

      {(checklist.priorityActions || []).length > 0 && (
        <Card variant="outlined">
          <CardContent>
            <Typography variant="subtitle1" gutterBottom>
              Priority actions
            </Typography>
            <List dense>
              {checklist.priorityActions!.map((action, index) => {
                const label = action.action || action.title || 'ISO assurance gap';
                const detail = action.detail || action.description;
                const hubLink = action.hubLink || '/compliance/india?section=iso-assurance';
                const buttonLabel = action.actionLabel || 'Close gap';
                return (
                <ListItem
                  key={action.gapId || action.action || action.title || index}
                  disableGutters
                  secondaryAction={(
                    <Button
                      size="small"
                      component={RouterLink}
                      to={hubLink}
                      endIcon={<ArrowForwardIcon />}
                    >
                      {buttonLabel}
                    </Button>
                  )}
                >
                  <ListItemText
                    primary={(
                      <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                        {action.priority ? (
                          <Chip
                            size="small"
                            color={action.priority === 'high' ? 'error' : action.priority === 'medium' ? 'warning' : 'default'}
                            variant="outlined"
                            label={action.priority}
                          />
                        ) : null}
                        <Typography variant="body2">{label}</Typography>
                        <Chip size="small" color="success" variant="outlined" label="~+12%" />
                      </Stack>
                    )}
                    secondary={detail}
                  />
                </ListItem>
                );
              })}
            </List>
            <ApplicationWarningResolver
              compact
              period={period}
              warnings={(checklist.priorityActions || []).slice(0, 3).map((action) => ({
                type: 'assurance_gate_blocked',
                message: action.action || action.title || 'ISO assurance gap',
                detail: action.detail || action.description,
                hubLink: action.hubLink || '/compliance/india?section=iso-assurance',
              }))}
            />
          </CardContent>
        </Card>
      )}
    </Stack>
  );
};

export default IsoGapClosurePanel;
